-- 바-ㅇ탈출 상세 콘텐츠 — 8/29 그룹 회차 페이지에서 옮겨온 것.
--
-- 적용: test 적용 완료 (2026-09-11) / ⚠️ 운영 미적용
-- 출처: src/app/(site)/sessions/[slug]/page.tsx 의 그룹(비소개팅) 분기
--   GROUP_FOR_YOU_CARDS / contentSteps / schedule / precautions / faqItems
--
-- 바꾼 것 둘:
--   1. 진행 순서는 절대시각(13:00…) 대신 시작 후 경과 분으로 넣는다.
--      회차마다 시작 시각이 달라도(11:30 / 15:30 / 19:30) 자동으로 맞는다.
--   2. 중복 참여 안내에서 "(그룹, 소개팅 무관)" 을 뺐다. 소개팅 버전이 없어졌다.
--   3. 섹션 라벨(FOR YOU / CONTENTS / SCHEDULE / PLEASE CHECK / FAQ)과 목록 모양
--      (컨텐츠 구성은 STEP 배지)까지 원래 화면과 같게 맞췄다.
--
-- 되돌리기: update public.themes
set content = $wye${"blocks": [{"type": "list", "title": "이런 분들에게 추천드려요", "items": [{"emoji": "🙋", "title": "새로운 사람들과 편하게 어울리고 싶은 분", "desc": "혼자 와도 팀 배정으로 자연스럽게 어울릴 수 있어요"}, {"emoji": "🤝", "title": "낯가림 없이 자연스럽게 친해지고 싶은 분", "desc": "방탈출이라는 공통 목표 덕분에 어색함 없이 금방 가까워져요"}, {"emoji": "🧩", "title": "방탈출・이색 액티비티를 좋아하는 분", "desc": "게임하듯 즐기다 보면 시간이 어느새 훌쩍 지나가요"}, {"emoji": "🎉", "title": "친구・지인과 색다른 모임을 즐기고 싶은 분", "desc": "뻔한 술자리 모임 말고, 콘텐츠가 있는 만남을 즐길 수 있어요"}], "eyebrow": "FOR YOU", "variant": "card"}, {"type": "list", "title": "컨텐츠 구성", "items": [{"emoji": "🧊", "title": "아이스브레이킹", "desc": "배정된 팀원과 간단한 스몰토크로 친해지는 시간. 팀은 저희가 방탈출 경험수 밸런스 조정해서 정해드려요."}, {"emoji": "🚪", "title": "방탈출 플레이", "desc": "팀별로 제한 시간 안에 함께 문제를 풀며 포인트를 수집합니다. 협동 과정에서 자연스럽게 팀워크가 발휘돼요."}, {"emoji": "💬", "title": "프리토킹 & 상품교환", "desc": "1부 컨텐츠 종료 후 다과와 함께하는 자유 대화 시간. 마음에 든 사람과 수다떨며 교류할 수 있어요. 추가로, 방탈출을 하며 수집했던 포인트로 여러가지 상품을 교환해보세요!"}], "eyebrow": "CONTENTS", "variant": "step"}, {"type": "timetable", "title": "진행 순서", "items": [{"offset_min": 0, "title": "현장 접수 & 팀별 배치 확인", "desc": "참여 확인 후 이름표 배부, 팀별 좌석 안내에 따라 착석"}, {"offset_min": 40, "title": "1부 컨텐츠 안내", "desc": "방탈출 진행 규칙 안내 및 설명"}, {"offset_min": 60, "title": "방탈출 진행 + 미니게임", "desc": "팀별 방탈출 진행. 돌발 미니게임 발생"}, {"offset_min": 150, "title": "2부 다과 타임 & 상품교환", "desc": "자유롭게 대화하며 수집한 포인트로 상품 교환 후 자율 퇴장"}], "eyebrow": "SCHEDULE"}, {"type": "text", "title": "", "body": "*자세한 타임테이블은 현장 상황에 따라 상이할 수 있습니다."}, {"type": "callout", "title": "참가 전 꼭 확인해주세요", "items": [{"title": "시작 24시간 이내 환불 불가", "desc": "테마 시작 24시간 전 이후부터는 환불이 불가합니다. 추가로, 노쇼 및 지각 시 입금액은 환불드리지 않으며 추후 이용이 제한될 수 있습니다."}, {"title": "참가 가능 나이 제한", "desc": "비슷한 연령끼리 즐기실 수 있도록 1987~2007년생만 신청 가능합니다."}, {"title": "결제는 무통장입금만 가능", "desc": "신청 후 30분 내 미입금 시 자동 취소됩니다."}, {"title": "진행 장소는 추후 안내", "desc": "정확한 참여 장소는 참여 확정 후 테마 시작 24시간 전에 문자로 안내드립니다."}, {"title": "동일 테마 중복 참여 불가", "desc": "동일 테마로 진행되는 회차들은 1인 1번만 참여 가능합니다."}, {"title": "휴대폰 사용 제한", "desc": "1부 진행 동안 사진 촬영을 포함한 모든 전자기기 사용이 제한됩니다. 사전 휴대폰 제출에 동의하신 분만 참여 가능합니다."}, {"title": "건강한 경쟁 매너 필수", "desc": "1부 전반적으로 경쟁 요소가 포함되어 있습니다. 과한 몰입보다 즐겁게 참여 부탁드립니다."}, {"title": "매너 있는 교류 필수", "desc": "타 참여자 및 진행자에게 과도한 신체 접촉 및 불쾌감을 유발하는 언행은 즉시 퇴장됩니다."}], "eyebrow": "PLEASE CHECK"}, {"type": "faq", "eyebrow": "FAQ", "title": "자주 묻는 질문", "items": [{"q": "혼자 또는 친구와 신청해도 되나요?", "a": "혼자 또는 친구와 함께 모두 가능합니다. 친구와 함께 신청 시 같은 팀으로 편성되고 싶으신 분들은 비고란에 작성해주시면 최대한 반영해드리겠습니다."}, {"q": "방탈출을 못 해봤는데 참여할 수 있나요?", "a": "전혀 문제없어요! 난이도는 초보자도 즐길 수 있는 수준으로 구성되며, 방탈출만이 아닌 미니게임들도 구성되어 있어 아쉬움 없이 모두 참여 가능합니다."}, {"q": "옷차림이나 준비물이 있나요?", "a": "단정한 옷차림과 신분증만 지참해주세요."}, {"q": "식사 제공 되나요?", "a": "식사는 별도로 제공되지 않지만, 커피 또는 아이스티와 함께 간단한 다과가 준비됩니다. 원활한 참여를 위해 식사를 미리 하고 오시는 것을 권장드립니다."}]}]}$wye$::jsonb,
    updated_at = now()
where slug = 'baotalchul';
